import{_ as l,a0 as p,w as o,s as r,ao as d,I as i,x as s,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 文件系统中使用 attr 添加扩展属性 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 文件系统中使用 attr 添加扩展属性 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 文件系统中使用 attr 添加扩展属性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 文件系统中使用 attr 添加扩展属性 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20220620 How I use the attr command with my Linux filesystem","title":"在 Linux 文件系统中使用 attr 添加扩展属性","tag":"202309","desc":""},"relativePath":"202309/20220620 How I use the attr command with my Linux filesystem.md","filePath":"[post].md"}'),c={name:"202309/20220620 How I use the attr command with my Linux filesystem.md"};function h(u,a,g,f,m,b){const e=p("Link");return o(),r("div",null,[a[15]||(a[15]=d(`<h1 id="在-linux-文件系统中使用-attr-添加扩展属性" tabindex="-1">在 Linux 文件系统中使用 attr 添加扩展属性 <a class="header-anchor" href="#在-linux-文件系统中使用-attr-添加扩展属性" aria-label="Permalink to “在 Linux 文件系统中使用 attr 添加扩展属性”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/15/081240syst7uisttadnky6.jpg" alt=""></p><blockquote><p>我使用开源的 XFS 文件系统是为了其扩展属性带来的小小便利。扩展属性是一种为我的数据添加上下文的独特方式。</p></blockquote><p>“文件系统” 是一个描述你的计算机怎样跟踪你创建的所有文件的完美词语。你的计算机存储有大量的数据，无论是文档、配置文件还是数以千计的照片。这需要一种对人和机器都友好的方式。诸如 Ext4、XFS、JFS、BtrFS 的文件系统是你的计算机用来跟踪文件的“语言”。</p><p>你的桌面或终端可以帮助你快速查找文件。例如，你的文件管理器可能有过滤功能，以便让你可以快速查看家目录内的图片，它也可能带有搜索功能以让你使用文件名定位文件。这些特性被称作<em>文件属性</em>，正如其名，它们是由文件头或者文件系统代码定义的文件对象的属性。大多数的文件系统记录了标准的文件属性，例如文件名、文件大小、文件类型、创建时间、上次访问时间等。</p><p>我在我的计算机上使用开源的 XFS 文件系统，不是为了其稳定性和高性能，而是为了其扩展属性带来的小小便利。</p><h3 id="常见的文件属性" tabindex="-1">常见的文件属性 <a class="header-anchor" href="#常见的文件属性" aria-label="Permalink to “常见的文件属性”">​</a></h3><p>当你保存一个文件，文件相关的数据也会随同保存。常见的属性会告诉操作系统是否更新访问时间，什么时间同步数据到硬盘等逻辑细节。哪些属性被保存取决于底层文件系统的功能和特性。</p><p>在标准文件属性（如果有标准属性的话）之外，XFS、Ext4 和 BtrFS 文件系统都可以使用扩展属性。</p><h3 id="扩展属性" tabindex="-1">扩展属性 <a class="header-anchor" href="#扩展属性" aria-label="Permalink to “扩展属性”">​</a></h3><p>XFS、Ext4 和 BtrFs 允许你创建自己的任意文件属性。由于是自己创建的，操作系统不会有内建支持，不过我以“标签”的方式使用它们，就像图片的 EXIF 数据一样。开发者们也许会选择使用扩展属性去开发应用内的自定义的功能。</p><p>XFS 中的属性有两个“命名空间”：用户（<code>user</code>）和根（<code>root</code>）。当创建属性时，你必须将其加入其中一个命名空间。要将属性添加到根命名空间，必须使用 <code>sudo</code> 命令或以 <code>root</code> 身份登录。</p><h3 id="增加一个属性" tabindex="-1">增加一个属性 <a class="header-anchor" href="#增加一个属性" aria-label="Permalink to “增加一个属性”">​</a></h3><p>你可以使用 <code>attr</code> 和 <code>setfattr</code> 命令在 XFS 文件系统中为文件增加属性。</p><p><code>attr</code> 命令默认在 <code>user</code> 命名空间下进行，所以你只需要为属性设置一个名字（<code>-s</code>）和值（<code>-V</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -s flavor -V vanilla example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; set to a 7 byte value for example.txt:</span></span>
<span class="line"><span>vanilla</span></span></code></pre></div><p><code>setfattr</code> 命令需要你指定目标命名空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ setfattr --name user.flavor --value chocolate example.txt</span></span></code></pre></div><h3 id="列出扩展文件属性" tabindex="-1">列出扩展文件属性 <a class="header-anchor" href="#列出扩展文件属性" aria-label="Permalink to “列出扩展文件属性”">​</a></h3><p>使用 <code>attr</code> 或者 <code>getfattr</code> 命令可以看已添加到文件上的扩展属性。<code>attr</code> 命令默认使用 <code>user</code> 空间，使用 <code>-g</code> 以获取扩展属性：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -g flavor example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; had a 9 byte value for example.txt:</span></span>
<span class="line"><span>chocolate</span></span></code></pre></div><p><code>getfattr</code> 命令需要属性的命名空间和名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getfattr --name user.flavor example.txt </span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;chocolate&quot;</span></span></code></pre></div><h3 id="列出所有扩展属性" tabindex="-1">列出所有扩展属性 <a class="header-anchor" href="#列出所有扩展属性" aria-label="Permalink to “列出所有扩展属性”">​</a></h3><p>要看一个文件的所有扩展属性，你可以使用 <code>attr -l</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ attr -l example.txt</span></span>
<span class="line"><span>Attribute &quot;md5sum&quot; has a 32 byte value for example.txt</span></span>
<span class="line"><span>Attribute &quot;flavor&quot; has a 9 byte value for example.txt</span></span></code></pre></div><p>或者，你也可以使用 <code>getfattr -d</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getfattr -d example.txt</span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;chocolate&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><p>扩展文件属性可以使用 <code>attr</code> 和 <code>setfattr</code> 更新，就像你创建这些属性一样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ setfattr --name user.flavor --value strawberry example.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ getfattr -d example.txt</span></span>
<span class="line"><span># file: example.txt</span></span>
<span class="line"><span>user.flavor=&quot;strawberry&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><h3 id="其他文件系统上的属性" tabindex="-1">其他文件系统上的属性 <a class="header-anchor" href="#其他文件系统上的属性" aria-label="Permalink to “其他文件系统上的属性”">​</a></h3><p>使用扩展属性最大的风险是忘记这些属性是特定于某个文件系统的。这意味着当你从一个磁盘或分区复制文件到另外一个磁盘或分区时，这些属性都会丢失，<strong>即使</strong>目标位置的文件系统也支持扩展属性。</p><p>为了避免丢失扩展属性，你需要使用支持保留这些属性的工具，例如 <code>rsync</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync --archive --xattrs ~/example.txt /tmp/</span></span></code></pre></div><p>但无论你使用什么工具，如果你传输文件到一个不知道如何处理扩展属性的文件系统，这些属性都会被丢弃。</p><h3 id="搜索属性" tabindex="-1">搜索属性 <a class="header-anchor" href="#搜索属性" aria-label="Permalink to “搜索属性”">​</a></h3><p>与扩展属性交互的机制并不多，所以使用这些添加的文件属性的方法也有限。我使用扩展属性作为标签机制，这让我可以将没有明显关系的文件联系起来。例如，假设我需要在一个项目中用“知识共享”的图形。假如我预见性地将 <code>license</code> 属性添加到了我的图形库中，我就可以使用 <code>find</code> 和 <code>getfattr</code> 在图形文件夹中寻找：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~/Graphics/ -type f \\</span></span>
<span class="line"><span>    -exec getfattr \\</span></span>
<span class="line"><span>    --name user.license \\</span></span>
<span class="line"><span>    -m cc-by-sa {} \\; 2&gt;/dev/null</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file: /home/tux/Graphics/Linux/kde-eco-award.png</span></span>
<span class="line"><span>user.license=&quot;cc-by-sa&quot;</span></span>
<span class="line"><span>user.md5sum=&quot;969181e76237567018e14fe1448dfd11&quot;</span></span></code></pre></div><h3 id="文件系统的秘密" tabindex="-1">文件系统的秘密 <a class="header-anchor" href="#文件系统的秘密" aria-label="Permalink to “文件系统的秘密”">​</a></h3><p>文件系统一般不会引起你的注意。它们实际是定义文件的系统。这不是计算机做的最让人兴奋的任务，也不是用户应该关心的东西。但是有些文件系统可以给你有趣、安全的特殊能力，扩展文件属性就是一个好例子。它的用途可能有限，但是扩展属性是你为数据增加上下文的独特方法。</p><p><em>（题图：MJ/06c0c478-7af7-49e4-836b-a9923db9dc0c）</em></p><hr>`,42)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),t(e,{href:"https://opensource.com/article/22/6/linux-attr-command"},{default:n(()=>[...a[0]||(a[0]=[s("https://opensource.com/article/22/6/linux-attr-command",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=s("作者：",-1)),t(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[2]||(a[2]=[s("Seth Kenlon",-1)])]),_:1}),a[7]||(a[7]=s(" 选题：",-1)),t(e,{href:"https://github.com/lkxed"},{default:n(()=>[...a[3]||(a[3]=[s("lkxed",-1)])]),_:1}),a[8]||(a[8]=s(" 译者：",-1)),t(e,{href:"https://github.com/wznmickey"},{default:n(()=>[...a[4]||(a[4]=[s("wznmickey",-1)])]),_:1}),a[9]||(a[9]=s(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[s("Linux中国",-1)])]),_:1}),a[14]||(a[14]=s(" 荣誉推出",-1))])])}const v=l(c,[["render",h]]);export{y as __pageData,v as default};
